<span class="line">            <span class="token class-name">LoginResp</span> resp <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">LoginResp</span><span class="token punctuation">(</span>newToken<span class="token punctuation">,</span> user<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
