<span class="line">            <span class="token keyword">return</span> <span class="token class-name">HttpResult</span><span class="token punctuation">.</span><span class="token function">error</span><span class="token punctuation">(</span><span class="token number">401</span><span class="token punctuation">,</span> <span class="token string">&quot;Token 无效或已过期&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
